class Solution
{
public:
    void reverseWords(vector< char>& s)
    {
        reverse(s.begin(), s.end());
        int n = s.size();
        for (int i = 0; i < n;)
        {
            int j = i;
            while (j < n && s[j] != ' ')++j;
            reverse(s.begin() + i, s.begin() + j);
            i = j + 1;
        }
    }
};
